contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, bool freeze) public {
        require(target != address(0));
        bool before = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, freeze); if (__ESBMC_reverted()) return;
        bool after1 = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, !freeze); if (__ESBMC_reverted()) return;
        bool after2 = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        assert(after1 == freeze && after2 == !freeze && (before == freeze || !before));
    }
    receive() external payable {}
}

